alter table public.health_jurisdictions add column if not exists authority_level text check(authority_level in ('city','state_province','country')),add column if not exists created_by uuid references auth.users(id),add column if not exists created_at timestamptz not null default now();
create table public.health_department_rules(id uuid primary key default gen_random_uuid(),jurisdiction_id uuid not null references public.health_jurisdictions(id) on delete cascade,rule_category text not null check(rule_category in ('prenatal_visit','partograph','maternal_alert','reporting')),name text not null,description text not null,requirements jsonb not null default '{}'::jsonb,effective_from date not null,effective_to date,active boolean not null default true,created_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from));
alter table public.prenatal_episodes add column if not exists gravida integer,add column if not exists para integer,add column if not exists last_menstrual_period date,add column if not exists pregnancy_status text not null default 'active' check(pregnancy_status in ('active','delivered','closed','lost_to_follow_up'));
alter table public.prenatal_visits add column if not exists gestational_age_weeks numeric(4,1),add column if not exists maternal_weight_kg numeric(7,2),add column if not exists systolic_bp integer,add column if not exists diastolic_bp integer,add column if not exists temperature_c numeric(5,2),add column if not exists pulse_rate integer,add column if not exists respiratory_rate integer,add column if not exists oxygen_saturation numeric(5,2),add column if not exists fundal_height_cm numeric(5,1),add column if not exists fetal_heart_rate integer,add column if not exists fetal_presentation text,add column if not exists fetal_movement text,add column if not exists edema text,add column if not exists urine_protein text,add column if not exists urine_glucose text,add column if not exists hemoglobin numeric(5,2),add column if not exists blood_group text,add column if not exists rh_factor text,add column if not exists danger_signs text,add column if not exists counseling text,add column if not exists treatment_plan text,add column if not exists next_visit_at timestamptz,add column if not exists recorded_by uuid references auth.users(id),add constraint prenatal_visit_oxygen_check check(oxygen_saturation is null or oxygen_saturation between 0 and 100);
create table public.partographs(id uuid primary key default gen_random_uuid(),episode_id uuid not null references public.prenatal_episodes(id) on delete cascade,encounter_id bigint references public.encounters(id),labor_started_at timestamptz not null,status text not null default 'active' check(status in ('active','delivery','transferred','closed')),rupture_of_membranes_at timestamptz,delivery_at timestamptz,outcome text,opened_by uuid not null references auth.users(id),closed_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.partograph_observations(id bigint generated by default as identity primary key,partograph_id uuid not null references public.partographs(id) on delete cascade,observed_at timestamptz not null,fetal_heart_rate integer,amniotic_fluid text,moulding text,cervical_dilation_cm numeric(4,1),head_descent_fifths numeric(3,1),contractions_per_10_minutes integer,contraction_duration_seconds integer,maternal_pulse integer,systolic_bp integer,diastolic_bp integer,temperature_c numeric(5,2),urine_volume_ml numeric(9,2),urine_protein text,urine_acetone text,oxytocin_dose text,medications_fluids text,notes text,recorded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(cervical_dilation_cm is null or cervical_dilation_cm between 0 and 10),check(head_descent_fifths is null or head_descent_fifths between 0 and 5),check(contractions_per_10_minutes is null or contractions_per_10_minutes between 0 and 10));
do $$ declare t text;begin foreach t in array array['health_department_rules','partographs','partograph_observations'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create policy health_rules_read on public.health_department_rules for select to authenticated using(private.is_platform_root() or exists(select 1 from public.health_department_memberships hm where hm.jurisdiction_id=health_department_rules.jurisdiction_id and hm.user_id=(select auth.uid()) and hm.active) or exists(select 1 from public.facility_jurisdictions fj where fj.jurisdiction_id=health_department_rules.jurisdiction_id and private.is_facility_member(fj.facility_id)));
create policy health_rules_insert on public.health_department_rules for insert to authenticated with check(private.is_platform_root() or exists(select 1 from public.health_department_memberships hm join public.roles r on r.id=hm.role_id where hm.jurisdiction_id=health_department_rules.jurisdiction_id and hm.user_id=(select auth.uid()) and hm.active and r.role_code='health_department_admin'));
create policy health_rules_update on public.health_department_rules for update to authenticated using(private.is_platform_root() or exists(select 1 from public.health_department_memberships hm join public.roles r on r.id=hm.role_id where hm.jurisdiction_id=health_department_rules.jurisdiction_id and hm.user_id=(select auth.uid()) and hm.active and r.role_code='health_department_admin')) with check(private.is_platform_root() or exists(select 1 from public.health_department_memberships hm join public.roles r on r.id=hm.role_id where hm.jurisdiction_id=health_department_rules.jurisdiction_id and hm.user_id=(select auth.uid()) and hm.active and r.role_code='health_department_admin'));
create policy partographs_access on public.partographs for all to authenticated using(private.is_aal2() and exists(select 1 from public.prenatal_episodes e where e.id=episode_id and private.is_facility_member(e.facility_id))) with check(private.is_aal2() and exists(select 1 from public.prenatal_episodes e where e.id=episode_id and private.is_facility_member(e.facility_id)));
create policy partograph_observations_access on public.partograph_observations for all to authenticated using(private.is_aal2() and exists(select 1 from public.partographs p join public.prenatal_episodes e on e.id=p.episode_id where p.id=partograph_id and private.is_facility_member(e.facility_id))) with check(private.is_aal2() and exists(select 1 from public.partographs p join public.prenatal_episodes e on e.id=p.episode_id where p.id=partograph_id and private.is_facility_member(e.facility_id)));
grant select,insert,update on public.health_department_rules,public.partographs,public.partograph_observations to authenticated;grant usage,select on all sequences in schema public to authenticated;
create index health_rules_jurisdiction_active_idx on public.health_department_rules(jurisdiction_id,rule_category,effective_from desc) where active;create index partographs_episode_idx on public.partographs(episode_id,labor_started_at desc);create index partograph_observations_time_idx on public.partograph_observations(partograph_id,observed_at);
create or replace function private.enforce_female_prenatal_patient() returns trigger language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.patients p where p.id=new.patient_id and lower(coalesce(p.sex,'')) in ('female','f')) then raise exception 'Prenatal episodes are available only for patients recorded as female';end if;return new;end $$;
drop trigger if exists enforce_female_prenatal_patient on public.prenatal_episodes;create trigger enforce_female_prenatal_patient before insert or update of patient_id on public.prenatal_episodes for each row execute function private.enforce_female_prenatal_patient();revoke all on function private.enforce_female_prenatal_patient() from public,anon,authenticated;
